const ExcelJS = require('exceljs');
function readBinaryBuffer(bin) {
  if (!bin || !bin.id || bin.data !== 'filesystem-v2') {
    return Buffer.from((bin && bin.data) || '', 'base64');
  }
  const fs = require('fs'), path = require('path');
  const rel = bin.id.replace(/^filesystem-v2:/, '');
  const bases = [
    process.env.N8N_BINARY_DATA_STORAGE_PATH,
    process.env.N8N_USER_FOLDER && path.join(process.env.N8N_USER_FOLDER, 'binaryData'),
    '/home/node/.n8n/binaryData',
    path.join(process.env.HOME || '/home/node', '.n8n', 'binaryData'),
  ].filter(Boolean);
  for (const base of bases) {
    const full = path.join(base, rel);
    if (fs.existsSync(full)) return fs.readFileSync(full);
  }
  throw new Error('Archivo binario no encontrado: ' + bases.join(', '));
}

function readCell(ws, coord) {
  const cell = ws.getCell(coord);
  const v = cell.value;
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') {
    if (v.richText) return v.richText.map(t => t.text).join('');
    if (v.text) return String(v.text);
    if (v.result !== undefined) return String(v.result);
    return String(v);
  }
  return String(v).trim();
}

const item = $input.first();
if (!item?.binary) return [{ json: { error: 'Sin archivo adjunto al formulario', briefs: [] } }];

let xlsxBin = null, xlsxFieldName = null;
const bin = item.binary;

for (const [k, b] of Object.entries(bin)) {
  const key = k.toLowerCase();
  const fname = (b.fileName || k).toLowerCase();
  if ((key.includes('plantilla') || key.includes('brief')) && (fname.endsWith('.xlsx') || fname.endsWith('.xlsm'))) {
    xlsxBin = b; xlsxFieldName = k; break;
  }
}
if (!xlsxFieldName) {
  for (const [k, b] of Object.entries(bin)) {
    const fname = (b.fileName || k).toLowerCase();
    if (fname.endsWith('.xlsx') || fname.endsWith('.xlsm')) { xlsxBin = b; xlsxFieldName = k; break; }
  }
}
if (!xlsxFieldName) return [{ json: { error: 'No se encontro plantilla .xlsx en los adjuntos', briefs: [] } }];

const buffer = readBinaryBuffer(xlsxBin);
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);

const briefs = [];
for (const ws of wb.worksheets) {
  const max = Math.min(ws.rowCount || 200, 500);
  for (let r = 1; r <= max; r++) {
    if (readCell(ws, `A${r}`).toLowerCase() !== 'tema') continue;
    const b = r - 1;
    const tema = readCell(ws, `B${b+1}`);
    if (!tema.trim()) continue;
    if (readCell(ws, `B${b+2}`).trim()) continue;

    // Detect clasificacion data row dynamically
    let clasifRow = b + 12;
    for (let cr = b+9; cr <= b+20; cr++) {
      if (readCell(ws, `A${cr}`).toLowerCase() === 'eje de contenido') {
        clasifRow = cr + 1;
        break;
      }
    }

    briefs.push({
      sheet: ws.name, baseRow: r, tema,
      objetivo: readCell(ws, `B${b+4}`),
      descripcion: readCell(ws, `B${b+5}`),
      clasificacion: {
        eje: readCell(ws, `A${clasifRow}`),
        tipo: readCell(ws, `C${clasifRow}`),
        formato: readCell(ws, `G${clasifRow}`),
        etapa: readCell(ws, `J${clasifRow}`)
      }
    });
  }
}

return [{ json: { briefs, fileName: xlsxBin.fileName, briefCount: briefs.length }, binary: { template: xlsxBin } }];

function readBinaryBuffer(bin) {
  if (!bin || !bin.id || bin.data !== 'filesystem-v2') {
    return Buffer.from((bin && bin.data) || '', 'base64');
  }
  const fs = require('fs'), path = require('path');
  const rel = bin.id.replace(/^filesystem-v2:/, '');
  const bases = [
    process.env.N8N_BINARY_DATA_STORAGE_PATH,
    process.env.N8N_USER_FOLDER && path.join(process.env.N8N_USER_FOLDER, 'binaryData'),
    '/home/node/.n8n/binaryData',
    path.join(process.env.HOME || '/home/node', '.n8n', 'binaryData'),
  ].filter(Boolean);
  for (const base of bases) {
    const full = path.join(base, rel);
    if (fs.existsSync(full)) return fs.readFileSync(full);
  }
  throw new Error('Archivo binario no encontrado: ' + bases.join(', '));
}

