function detectClient(s) {
  const r = (s||'').toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g,'');
  if (!r) return null;
  if (r.includes('rosario')||r.includes('urosario')) return 'rosario';
  if (r.includes('usmp')||r.includes('san martin')) return 'usmp';
  if (r.includes('anahuac')) return 'anahuac';
  if (r.includes('unapec')) return 'unapec';
  if (r.includes('continental')) return 'continental';
  if (r.includes('sabana')) return 'sabana';
  if (r.includes('udla')) return 'udla';
  if (r.includes('pucmm')) return 'pucmm';
  if (r.includes('javeriana')) return 'javeriana';
  if (r.includes('ulatina')||r.includes('u. latina')) return 'ulatina';
  if (r.includes('unibe')) return 'unibe';
  if (r.includes('upb')||r.includes('bolivariana')) return 'upb';
  if (r.includes('utb')||r.includes('tecnologica')) return 'utb';
  if (r.includes('udem')||r.includes('monterrey')) return 'udem';
  return CLIENTES[r] ? r : null;
}

const CA = {
  keyword: ['Keyword','Phrase','Palabra clave','Ph','Query'],
  volumen: ['Volume','Search Volume','Avg. monthly searches','Volumen','Nq','Monthly Searches','Vol.'],
  kd:      ['Keyword Difficulty','KD','Difficulty','Dificultad','Kd','KD %','KD (%)'],
  cpc:     ['CPC','CPC (USD)','Cp'],
  intent:  ['Intent','Search Intent','Intencion']
};

function delim(line) {
  const s=(line.match(/;/g)||[]).length, c=(line.match(/,/g)||[]).length, t=(line.match(/\t/g)||[]).length;
  if(t>s&&t>c) return '\t'; return s>c?';':','
}

function parseCSV(txt, d) {
  if(txt.charCodeAt(0)===0xFEFF) txt=txt.slice(1);
  const rows=[]; let row=[],f='',q=false;
  for(let i=0;i<txt.length;i++){
    const c=txt[i];
    if(q){if(c=='"'&&txt[i+1]=='"'){f+='"';i++;}else if(c=='"'){q=false;}else{f+=c;}}
    else{if(c=='"'){q=true;}else if(c===d){row.push(f);f='';}else if(c=='\n'||c=='\r'){if(c=='\r'&&txt[i+1]=='\n')i++;if(f!==''||row.length>0){row.push(f);rows.push(row);}row=[];f='';}else{f+=c;}}
  }
  if(f!==''||row.length>0){row.push(f);rows.push(row);}
  if(rows.length<2) return [];
  const headers=rows[0].map(h=>h.trim());
  return rows.slice(1).map(r=>{const o={};headers.forEach((h,i)=>{o[h]=(r[i]||'').trim();});return o;});
}

function findCol(headers, aliases) {
  const lh=headers.map(h=>h.toLowerCase());
  for(const a of aliases){const i=lh.indexOf(a.toLowerCase());if(i>=0) return headers[i];}
  for(const a of aliases){const found=headers.find(h=>h.toLowerCase().includes(a.toLowerCase()));if(found) return found;}
  return null;
}

function pNum(raw) {
  if(raw===null||raw===undefined||raw==='') return null;
  const s=String(raw).replace(/[^0-9.,-]/g,'');
  if(!s) return null;
  let n;
  if(s.includes('.')&&s.includes(',')) n=s.replace(/,/g,'');
  else if(s.includes(',')&&!s.includes('.')) n=/,\d{3}$/.test(s)?s.replace(/,/g,''):s.replace(',','.');
  else n=s;
  const v=parseFloat(n); return isNaN(v)?null:v;
}

const formItem = $('Webhook').first();
const leerItem = $input.first();

const clienteRaw = formItem.json['Cliente'] || formItem.json?.body?.['Cliente'] || '';
const categoriaRaw = formItem.json['Categoria del blog'] || formItem.json?.body?.['Categoria del blog'] || formItem.json['Categoría del blog'] || formItem.json?.body?.['Categoría del blog'] || '';
const categoria = categoriaRaw.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,'-');
const key = detectClient(clienteRaw);
const cfg = key ? CLIENTES[key] : null;

const fb = formItem.binary || formItem.json?.body?.binary || {};

let candidates=[], stats={filesProcessed:0,rowsRead:0,kept:0,dropped:{volume:0,kd:0,dup:0,missing:0}};
const globalKwMap=new Map();

function parseSemrushContent(content) {
  const d=delim(content.split('\n')[0]||'');
  return parseCSV(content,d);
}

for(const [k,b] of Object.entries(fb)){
  const fn=(b.fileName||k).toLowerCase();
  const kl=k.toLowerCase();
  if(kl.includes('plantilla')||kl.includes('brief')||fn.includes('plantilla')) continue;
  if(!fn.endsWith('.csv')&&!fn.endsWith('.txt')) continue;
  const buf=readBinaryBuffer(b);
  let content=buf.toString('utf-8');
  if(content.includes('?')) content=buf.toString('latin1');
  if(!content.trim()) continue;
  const rows=parseSemrushContent(content);
  stats.filesProcessed++; stats.rowsRead+=rows.length;
  if(!rows.length) continue;
  const headers=Object.keys(rows[0]);
  const cols={keyword:findCol(headers,CA.keyword),volumen:findCol(headers,CA.volumen),kd:findCol(headers,CA.kd),cpc:findCol(headers,CA.cpc),intent:findCol(headers,CA.intent)};
  for(const row of rows){
    const rk=cols.keyword?row[cols.keyword]:''; if(!rk){stats.dropped.missing++;continue;}
    const kk=rk.toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ');
    if(!kk){stats.dropped.missing++;continue;}
    const vol=cols.volumen?Math.round(pNum(row[cols.volumen])||0):0;
    const kd=cols.kd?pNum(row[cols.kd]):null;
    if(vol<30){stats.dropped.volume++;continue;}
    if(kd!==null&&kd>60){stats.dropped.kd++;continue;}
    const ex=globalKwMap.get(kk);
    if(ex){stats.dropped.dup++;if(ex.volumen>=vol)continue;}
    globalKwMap.set(kk,{keyword:rk.trim(),volumen:vol,kd:kd!==null?Math.round(kd*10)/10:null,cpc:cols.cpc?pNum(row[cols.cpc]):null,intent:cols.intent?(row[cols.intent]||'').trim()||null:null});
  }
}

if(!stats.filesProcessed){
  const ExcelJS=require('exceljs');
  for(const [k,b] of Object.entries(fb)){
    const fn=(b.fileName||k).toLowerCase(),kl=k.toLowerCase();
    if(kl.includes('plantilla')||kl.includes('brief')||fn.includes('plantilla')) continue;
    if(!fn.endsWith('.xlsx')&&!fn.endsWith('.xlsm')) continue;
    const wb2=new ExcelJS.Workbook();
    await wb2.xlsx.load(readBinaryBuffer(b));
    const ws2=wb2.worksheets[0];
    const lines=[];
    ws2.eachRow(row=>{
      const vals=[];
      row.eachCell({includeEmpty:true},cell=>{
        let v=cell.value;
        if(v===null||v===undefined)v='';
        else if(typeof v==='object'){if(v.richText)v=v.richText.map(t=>t.text).join('');else if(v.text)v=String(v.text);else if(v.result!==undefined)v=String(v.result);else v=String(v);}
        vals.push(String(v).replace(/,/g,';'));
      });
      lines.push(vals.join(','));
    });
    if(lines.length<2) continue;
    const rows=parseSemrushContent(lines.join('\n'));
    stats.filesProcessed++; stats.rowsRead+=rows.length;
    if(!rows.length) continue;
    const headers=Object.keys(rows[0]);
    const cols={keyword:findCol(headers,CA.keyword),volumen:findCol(headers,CA.volumen),kd:findCol(headers,CA.kd),cpc:findCol(headers,CA.cpc),intent:findCol(headers,CA.intent)};
    for(const row of rows){
      const rk=cols.keyword?row[cols.keyword]:''; if(!rk){stats.dropped.missing++;continue;}
      const kk=rk.toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ');
      if(!kk){stats.dropped.missing++;continue;}
      const vol=cols.volumen?Math.round(pNum(row[cols.volumen])||0):0;
      const kd=cols.kd?pNum(row[cols.kd]):null;
      if(vol<30){stats.dropped.volume++;continue;}
      if(kd!==null&&kd>60){stats.dropped.kd++;continue;}
      const ex=globalKwMap.get(kk);
      if(ex){stats.dropped.dup++;if(ex.volumen>=vol)continue;}
      globalKwMap.set(kk,{keyword:rk.trim(),volumen:vol,kd:kd!==null?Math.round(kd*10)/10:null,cpc:cols.cpc?pNum(row[cols.cpc]):null,intent:cols.intent?(row[cols.intent]||'').trim()||null:null});
    }
  }
}

const sorted=Array.from(globalKwMap.values()).sort((a,b)=>{if(b.volumen!==a.volumen)return b.volumen-a.volumen;return(a.kd??999)-(b.kd??999);});
candidates=sorted.slice(0,40); stats.kept=candidates.length;

if(candidates.length===0&&stats.filesProcessed>0){
  const fallMap=new Map();
  for(const [k,b] of Object.entries(fb)){
    const fn=(b.fileName||k).toLowerCase(),kl=k.toLowerCase();
    if(kl.includes('plantilla')||kl.includes('brief')) continue;
    if(!fn.endsWith('.csv')&&!fn.endsWith('.txt')) continue;
    const buf=readBinaryBuffer(b);
    let content=buf.toString('utf-8');
    if(content.includes('?')) content=buf.toString('latin1');
    const rows=parseSemrushContent(content);
    if(!rows.length) continue;
    const headers=Object.keys(rows[0]);
    const cols={keyword:findCol(headers,CA.keyword),volumen:findCol(headers,CA.volumen),kd:findCol(headers,CA.kd),cpc:findCol(headers,CA.cpc),intent:findCol(headers,CA.intent)};
    for(const row of rows){
      const rk=cols.keyword?row[cols.keyword]:''; if(!rk) continue;
      const kk=rk.toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ');
      if(!kk) continue;
      const vol=cols.volumen?Math.round(pNum(row[cols.volumen])||0):0;
      const kd=cols.kd?pNum(row[cols.kd]):null;
      const ex=fallMap.get(kk);
      if(ex&&ex.volumen>=vol) continue;
      fallMap.set(kk,{keyword:rk.trim(),volumen:vol,kd:kd!==null?Math.round(kd*10)/10:null,cpc:cols.cpc?pNum(row[cols.cpc]):null,intent:cols.intent?(row[cols.intent]||'').trim()||null:null});
    }
  }
  candidates=Array.from(fallMap.values()).sort((a,b)=>b.volumen-a.volumen).slice(0,40);
  stats.kept=candidates.length; stats.fallback_sin_filtros=true;
}

const domain=cfg?.domain||'https://example.com';
const briefs=leerItem.json.briefs||[];

const internalUrls=[
  ...(cfg?.programas||[]).map(p=>({url:domain+p.url,anchor:p.anchor_default})),
