    if (v.result !== undefined) return String(v.result);
    return String(v);
  }
  return String(v).trim();
}

// Scan col A for section label — handles templates with different numbers of URL rows
function findRow(startRow, endRow, labelLower) {
  for (let r = startRow; r <= endRow; r++) {
    if (readCellStr(`A${r}`).toLowerCase() === labelLower) return r;
  }
  return null;
}

