function writeCell(coord, value) {
  if (value === null || value === undefined || value === '') return false;
  const cell = ws.getCell(coord);
  const merges = ws.model.merges || [];
  for (const range of merges) {
    let top, left, bottom, right;
    if (typeof range === 'string') {
      const m = range.match(/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/);
      if (m) {
        const colToNum = s => s.split('').reduce((a,c) => a*26+(c.charCodeAt(0)-64), 0);
        left=colToNum(m[1]); top=parseInt(m[2],10); right=colToNum(m[3]); bottom=parseInt(m[4],10);
      }
    } else if (range.top !== undefined) {
      ({ top, left, bottom, right } = range);
    }
    if (top !== undefined && cell.row>=top && cell.row<=bottom && cell.col>=left && cell.col<=right) {
      ws.getCell(top, left).value = value;
      return true;
    }
  }
  cell.value = value;
  return true;
}

