function detectClient(s) {
  const r = (s||'').toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g,'');
  if (!r) return null;
  if (r.includes('rosario')||r.includes('urosario')) return 'rosario';
  if (r.includes('usmp')||r.includes('san martin')) return 'usmp';
  if (r.includes('anahuac')) return 'anahuac';
  if (r.includes('unapec')) return 'unapec';
  if (r.includes('continental')) return 'continental';
  if (r.includes('sabana')) return 'sabana';
  if (r.includes('udla')) return 'udla';
  if (r.includes('pucmm')) return 'pucmm';
  if (r.includes('javeriana')) return 'javeriana';
  if (r.includes('ulatina')||r.includes('u. latina')) return 'ulatina';
  if (r.includes('unibe')) return 'unibe';
  if (r.includes('upb')||r.includes('bolivariana')) return 'upb';
  if (r.includes('utb')||r.includes('tecnologica')) return 'utb';
  if (r.includes('udem')||r.includes('monterrey')) return 'udem';
  return CLIENTES[r] ? r : null;
}

