  for(let i=0;i<txt.length;i++){
    const c=txt[i];
    if(q){if(c=='"'&&txt[i+1]=='"'){f+='"';i++;}else if(c=='"'){q=false;}else{f+=c;}}
    else{if(c=='"'){q=true;}else if(c===d){row.push(f);f='';}else if(c=='\n'||c=='\r'){if(c=='\r'&&txt[i+1]=='\n')i++;if(f!==''||row.length>0){row.push(f);rows.push(row);}row=[];f='';}else{f+=c;}}
  }
  if(f!==''||row.length>0){row.push(f);rows.push(row);}
  if(rows.length<2) return [];
  const headers=rows[0].map(h=>h.trim());
  return rows.slice(1).map(r=>{const o={};headers.forEach((h,i)=>{o[h]=(r[i]||'').trim();});return o;});
}

function findCol(headers, aliases) {
  const lh=headers.map(h=>h.toLowerCase());
  for(const a of aliases){const i=lh.indexOf(a.toLowerCase());if(i>=0) return headers[i];}
  for(const a of aliases){const found=headers.find(h=>h.toLowerCase().includes(a.toLowerCase()));if(found) return found;}
  return null;
}

function pNum(raw) {
  if(raw===null||raw===undefined||raw==='') return null;
  const s=String(raw).replace(/[^0-9.,-]/g,'');
  if(!s) return null;
  let n;
  if(s.includes('.')&&s.includes(',')) n=s.replace(/,/g,'');
  else if(s.includes(',')&&!s.includes('.')) n=/,\d{3}$/.test(s)?s.replace(/,/g,''):s.replace(',','.');
  else n=s;
  const v=parseFloat(n); return isNaN(v)?null:v;
}

