const ExcelJS = require('exceljs');
function readBinaryBuffer(bin) {
  if (!bin || !bin.id || bin.data !== 'filesystem-v2') {
    return Buffer.from((bin && bin.data) || '', 'base64');
  }
  const fs = require('fs'), path = require('path');
  const rel = bin.id.replace(/^filesystem-v2:/, '');
  const bases = [
    process.env.N8N_BINARY_DATA_STORAGE_PATH,
    process.env.N8N_USER_FOLDER && path.join(process.env.N8N_USER_FOLDER, 'binaryData'),
    '/home/node/.n8n/binaryData',
    path.join(process.env.HOME || '/home/node', '.n8n', 'binaryData'),
  ].filter(Boolean);
  for (const base of bases) {
    const full = path.join(base, rel);
    if (fs.existsSync(full)) return fs.readFileSync(full);
  }
  throw new Error('Archivo binario no encontrado: ' + bases.join(', '));
}

