function readCellStr(coord) {
  const v = ws.getCell(coord).value;
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') {
    if (v.richText) return v.richText.map(t => t.text).join('');
    if (v.text) return String(v.text);
    if (v.result !== undefined) return String(v.result);
    return String(v);
  }
  return String(v).trim();
}

// Scan col A for section label — handles templates with different numbers of URL rows
function findRow(startRow, endRow, labelLower) {
  for (let r = startRow; r <= endRow; r++) {
    if (readCellStr(`A${r}`).toLowerCase() === labelLower) return r;
  }
  return null;
}

const ejeHeaderRow   = findRow(b+9,  b+25, 'eje de contenido')      || (b+11);
const clasificRow    = ejeHeaderRow + 1;
const kwLabelRow     = findRow(clasificRow+1, b+28, 'keyword principal')     || (b+13);
const fechaLabelRow  = findRow(kwLabelRow+1,  b+28, 'fecha de analisis seo') || (b+14);
const kwTableRow     = findRow(fechaLabelRow+1, b+35, 'keyword principal')   || (b+16);
const kwDataRow      = kwTableRow + 1;
const kwSecHdrRow    = findRow(kwDataRow+1, b+45, 'keywords secundarias')    || (b+19);
const kwSecDataStart = kwSecHdrRow + 1;
const metaHdrRow     = findRow(kwSecDataStart+1, b+70, 'meta title')         || (b+26);
const metaDataRow    = metaHdrRow + 1;

function writeCell(coord, value) {
  if (value === null || value === undefined || value === '') return false;
  const cell = ws.getCell(coord);
  const merges = ws.model.merges || [];
  for (const range of merges) {
    let top, left, bottom, right;
    if (typeof range === 'string') {
      const m = range.match(/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/);
      if (m) {
        const colToNum = s => s.split('').reduce((a,c) => a*26+(c.charCodeAt(0)-64), 0);
        left=colToNum(m[1]); top=parseInt(m[2],10); right=colToNum(m[3]); bottom=parseInt(m[4],10);
      }
    } else if (range.top !== undefined) {
      ({ top, left, bottom, right } = range);
    }
    if (top !== undefined && cell.row>=top && cell.row<=bottom && cell.col>=left && cell.col<=right) {
      ws.getCell(top, left).value = value;
      return true;
    }
  }
  cell.value = value;
  return true;
}

